package com.example.urlshortener.preview;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

import java.time.Duration;
import java.util.Optional;

@Component
@ConditionalOnBean(StringRedisTemplate.class)
public class RedisPreviewCache implements PreviewCache {

    private static final String KEY_PREFIX = "preview:";

    private static final Logger log = LoggerFactory.getLogger(RedisPreviewCache.class);

    private final StringRedisTemplate redisTemplate;
    private final PreviewConfig config;
    private final ObjectMapper objectMapper;

    @Autowired
    public RedisPreviewCache(StringRedisTemplate redisTemplate, PreviewConfig config) {
        this.redisTemplate = redisTemplate;
        this.config = config;
        this.objectMapper = buildObjectMapper();
    }

    @Override
    public Optional<PreviewDocument> get(String code) {
        String key = KEY_PREFIX + code;
        try {
            String json = redisTemplate.opsForValue().get(key);
            if (json == null) {
                return Optional.empty();
            }
            PreviewDocument doc = objectMapper.readValue(json, PreviewDocument.class);
            return Optional.of(doc);
        } catch (Exception e) {
            log.warn("Failed to read preview from Redis for key {}: {}", key, e.getMessage());
            return Optional.empty();
        }
    }

    @Override
    public void put(String code, PreviewDocument document) {
        String key = KEY_PREFIX + code;
        try {
            String json = objectMapper.writeValueAsString(document);
            redisTemplate.opsForValue().setIfAbsent(key, json, Duration.ofSeconds(config.getCacheTtlSeconds()));
        } catch (JsonProcessingException e) {
            log.warn("Failed to serialize preview document for key {}: {}", key, e.getMessage());
        } catch (Exception e) {
            log.warn("Failed to write preview to Redis for key {}: {}", key, e.getMessage());
        }
    }

    private static ObjectMapper buildObjectMapper() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(new JavaTimeModule());
        mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
        return mapper;
    }
}
