package com.example.urlshortener.preview;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

import java.time.Instant;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

@Component
@ConditionalOnMissingBean(StringRedisTemplate.class)
public class InProcessPreviewCache implements PreviewCache {

    private static final Logger log = LoggerFactory.getLogger(InProcessPreviewCache.class);

    private final Map<String, CacheEntry> store = new ConcurrentHashMap<>();
    private final PreviewConfig config;

    public InProcessPreviewCache(PreviewConfig config) {
        this.config = config;
    }

    @Override
    public Optional<PreviewDocument> get(String code) {
        CacheEntry entry = store.get(code);
        if (entry == null) {
            return Optional.empty();
        }
        if (Instant.now().isAfter(entry.expiresAt)) {
            store.remove(code);
            log.debug("In-process cache entry expired for code {}", code);
            return Optional.empty();
        }
        return Optional.of(entry.document);
    }

    @Override
    public void put(String code, PreviewDocument document) {
        Instant expiresAt = Instant.now().plusSeconds(config.getCacheTtlSeconds());
        store.putIfAbsent(code, new CacheEntry(document, expiresAt));
    }

    private static class CacheEntry {
        final PreviewDocument document;
        final Instant expiresAt;

        CacheEntry(PreviewDocument document, Instant expiresAt) {
            this.document = document;
            this.expiresAt = expiresAt;
        }
    }
}
