                sb.append(line).append('\n');
                if (HEAD_END_PATTERN.matcher(sb).find()) {
                    break;
                }
                // Safety limit: don't read more than 64KB looking for head
                if (sb.length() > 65536) {
                    break;
                }
            }
        } finally {
            conn.disconnect();
        }
        return sb.toString();
    }

    private String extractTitle(String html) {
        Matcher m = TITLE_PATTERN.matcher(html);
        if (m.find()) {
            return m.group(1).trim();
        }
        return null;
    }

    private String extractDescription(String html) {
